/* @lc app=leetcode id=3273 lang=kotlin */ class Solution { fun minDamage(power: Int, damage: IntArray, health: IntArray): Long = damage.indices.sortedWith(Comparator<Int> { a, b -> (damage[b].toLong() * ((health[a] + power - 1) / power)).compareTo(damage[a].toLong() * ((health[b] + power - 1) / power)) }).fold(0L to 0L) { (t, tot), i -> ((health[i] + power - 1) / power).let { c -> t + c to tot + damage[i].toLong() * (t + c) } }.second }